        for (int j = 0; j < dim2; j++) {
            jsonArray3[i][j] = (JSONArray) jsonArray2[i].get(j);
            for (int k = 0; k < dim3; k++) {
                doubleArr[i][j][k] = (Double) jsonArray3[i][j].get(k);
