public Product(String name, String type, int sceneRasterWidth, int sceneRasterHeight){
    this(name, type, sceneRasterWidth, sceneRasterHeight, (ProductReader) null);
}

static Product findMasterProduct(List<Product> openProductList){
    int maxWidth = 0;
    int maxHeight = 0;
    Product masterProduct = null;
    for (Product product : openProductList) {
        final int width = product.getSceneRasterWidth();
        final int height = product.getSceneRasterHeight();
        if (width > maxWidth || height > maxHeight) {
            masterProduct = product;
            maxWidth = Math.max(maxWidth, width);
            maxHeight = Math.max(maxHeight, height);
        }
    }
    return masterProduct;
}

,"assertEquals(""p3"", masterProduct.getName())

