public PixelPos getPixelPos(GeoPos geoPos, PixelPos pixelPos){
    this.ensureApproximations();
    if (this.approximations != null) {
        double lat = normalizeLat(geoPos.lat);
        double lon = this.normalizeLon(geoPos.lon);
        if (pixelPos == null) {
            pixelPos = new PixelPos();
        }
        if (this.isValidGeoPos(lat, lon)) {
            Approximation approximation = getBestApproximation(this.approximations, lat, lon);
            if (lon >= this.overlapStart && lon <= this.overlapEnd) {
                double squareDistance;
                if (approximation != null) {
                    squareDistance = approximation.getSquareDistance(lat, lon);
                } else {
                    squareDistance = Double.MAX_VALUE;
                }
                double tempLon = lon + (double) 360.0F;
                Approximation renormalizedApproximation = this.findRenormalizedApproximation(lat, tempLon, squareDistance);
                if (renormalizedApproximation != null) {
                    approximation = renormalizedApproximation;
                    lon = tempLon;
                }
            }
            if (approximation != null) {
                lat = rescaleLatitude(lat);
                lon = rescaleLongitude(lon, approximation.getCenterLon());
                pixelPos.x = approximation.getFX().computeZ(lat, lon);
                pixelPos.y = approximation.getFY().computeZ(lat, lon);
            } else {
                pixelPos.setInvalid();
            }
        } else {
            pixelPos.setInvalid();
        }
    }
    return pixelPos;
}

public PixelPos getPixelPos(GeoPos geoPos, PixelPos pixelPos){
    pixelPos = super.getPixelPos(geoPos, pixelPos);
    PixelPos transformedPixelPos = new PixelPos();
    inverse.transform(pixelPos, transformedPixelPos);
    pixelPos.setLocation(transformedPixelPos);
    return transformedPixelPos;
}

