public static MultiLevelSource create(MultiLevelSource lonSource, MultiLevelSource latSource, LonLatFunction function, int targetDataType){
    argument(lonSource != null, "lonSource != null");
    argument(latSource != null, "latSource != null");
    argument(function != null, "function != null");
    Rectangle2D lonModelBounds = lonSource.getModel().getModelBounds();
    Rectangle2D latModelBounds = latSource.getModel().getModelBounds();
    argument(Objects.equals(lonModelBounds, latModelBounds), "Model bounds of lat and lon source must be equal");
    return new LonLatMultiLevelSource(lonSource, latSource, function, targetDataType);
}

