public Product(String name, String type, int sceneRasterWidth, int sceneRasterHeight){
    this(name, type, sceneRasterWidth, sceneRasterHeight, (ProductReader) null);
}

public MetadataElement getMetadataRoot(){
    return this.metadataRoot;
}

public MetadataElement(String name){
    super(name);
}

public void addElement(MetadataElement element){
    if (element != null) {
        if (this.elements == null) {
            this.elements = new ProductNodeGroup(this, "elements", true);
        }
        this.elements.add(element);
    }
