        }
        Double pixelSize = getValueDouble("MAP_PROJ_RESOLUTION");
        Double upperLeftLon = getValueDouble("CARTO_UPPER_LEFT_X");
        Double upperLeftLat = getValueDouble("CARTO_UPPER_LEFT_Y");
