// Invoked methods in test prefix
public Product(String name, String type, int sceneRasterWidth, int sceneRasterHeight){
    this(name, type, sceneRasterWidth, sceneRasterHeight, (ProductReader) null);
}

public Band(String name, int dataType, int width, int height){
    super(name, dataType, width, height);
    this.setSpectralBandIndex(-1);
    this.setModified(false);
}

public void setSpectralWavelength(float spectralWavelength){
    if (this.spectralWavelength != spectralWavelength) {
        this.spectralWavelength = spectralWavelength;
        this.fireProductNodeChanged("spectralWavelength");
        this.setModified(true);
    }
}

public void addBand(Band band){
    notNull(band, "band");
    argument(!this.containsRasterDataNode(band.getName()), "The Product '" + this.getName() + "' already contains a band with the name '" + band.getName() + "'.");
    this.bandGroup.add(band);
}

public DefaultReflectancesSelector(double[] wavelengths, String[] defaultNameRegex){
    this.wavelengths = wavelengths;
    this.defaultNameRegex = defaultNameRegex;
}

public String[] select(Product product, String userBandNameRegex){
    final Band[] bands = product.getBands();
    final ArrayList<String> band_Names = new ArrayList<>();
    List<String> regularexpressions = new ArrayList<>();
    if (StringUtils.isNotNullAndNotEmpty(userBandNameRegex)) {
        // use it only if set
        regularexpressions.add(userBandNameRegex);
    }
    regularexpressions.addAll(Arrays.asList(defaultNameRegex));
    // Fallback - Matches any name
    regularexpressions.add(FALLBACK_PATTERN);
    for (String regex : regularexpressions) {
        Pattern pattern = Pattern.compile(regex);
        for (double centralWl : wavelengths) {
            String name = null;
            double minDelta = Double.MAX_VALUE;
            for (Band band : bands) {
                if (!pattern.matcher(band.getName()).matches()) {
                    // skip this band if it doesn't match
                    continue;
                }
                double bandWavelength = band.getSpectralWavelength();
                if (bandWavelength > 0.0) {
                    double delta = Math.abs(bandWavelength - centralWl);
                    if (delta < minDelta && delta <= MAX_DELTA_WAVELENGTH) {
                        name = band.getName();
                        minDelta = delta;
                    }
                }
            }
            if (name != null) {
                band_Names.add(name);
            }
        }
        if (band_Names.size() == wavelengths.length) {
            // found all necessary bands
            return band_Names.toArray(new String[0]);
        }
        band_Names.clear();
    }
    return band_Names.toArray(new String[0]);
}

