// Invoked methods in test prefix
public static String extractBandName(String variableName){
    final int slashIndex = variableName.lastIndexOf('/');
    if (slashIndex > 0) {
        return variableName.substring(slashIndex + 1, variableName.length());
    }
    return variableName;
}

