    this.datasets = datasets;
    return this;
}

public InsituQuery latMin(Double latMin){
    this.latMin = latMin;
    return this;
}

public InsituQuery latMax(Double latMax){
    this.latMax = latMax;
    return this;
}

public InsituQuery lonMin(Double lonMin){
    this.lonMin = lonMin;
    return this;
}

public InsituQuery lonMax(Double lonMax){
    this.lonMax = lonMax;
    return this;
}

public InsituQuery startDate(Date startDate){
    this.startDate = startDate;
    return this;
}

public Date parse(String source) throws ParseException{
    ParsePosition pos = new ParsePosition(0);
    Date result = parse(source, pos);
    if (pos.index == 0)
        throw new ParseException("Unparseable date: \"" + source + "\"", pos.errorIndex);
    return result;
}

public InsituQuery stopDate(Date stopDate){
    this.stopDate = stopDate;
    return this;
}

public InsituQuery param(String[] parameters){
    this.param = parameters;
    return this;
}

public InsituQuery limit(int limit){
    this.limit = limit;
    return this;
}

public InsituQuery shift(int shift){
    this.shift = shift;
    return this;
}

public InsituQuery countOnly(boolean countOnly){
    this.countOnly = countOnly;
    return this;
}

public static String format(InsituQuery query){
    List<String> queryParams = new ArrayList<>();
    if (query.lonMin() != null) {
        queryParams.add(PARAM_LON_MIN + "=" + query.lonMin());
    }
    if (query.latMin() != null) {
        queryParams.add(PARAM_LAT_MIN + "=" + query.latMin());
    }
    if (query.lonMax() != null) {
        queryParams.add(PARAM_LON_MAX + query.lonMax());
    }
    if (query.latMax() != null) {
        queryParams.add(PARAM_LAT_MAX + "=" + query.latMax());
    }
    if (query.startDate() != null) {
        try {
            queryParams.add(PARAM_START_DATE + "=" + URLEncoder.encode(DATE_FORMAT.format(query.startDate()), "UTF-8"));
        } catch (UnsupportedEncodingException e) {
            throw new IllegalArgumentException("start date could not be encoded", e);
        }
    }
    if (query.stopDate() != null) {
        try {
            queryParams.add(PARAM_STOP_DATE + "=" + URLEncoder.encode(DATE_FORMAT.format(query.stopDate()), "UTF-8"));
        } catch (UnsupportedEncodingException e) {
            throw new IllegalArgumentException("stop date could not be encoded", e);
        }
    }
    if (query.param() != null && query.param().length > 0) {
        queryParams.add(PARAM_PARAM + "=" + StringUtils.arrayToCsv(query.param()));
    }
    if (query.datasets() != null && query.datasets().length > 0) {
        queryParams.add(PARAM_CAMPAIGN + "=" + StringUtils.arrayToCsv(query.datasets()));
    }
    if (query.shift() > 0) {
        queryParams.add(PARAM_SHIFT + "=" + query.shift());
    }
    if (query.limit() > 0) {
        queryParams.add(PARAM_LIMIT + "=" + query.limit());
    }
    if (query.countOnly()) {
        queryParams.add(PARAM_COUNT_ONLY);
    }
    if (query.subject() == null) {
        throw new IllegalArgumentException("subject must be specified");
    }
    final StringBuilder sb = new StringBuilder();
    sb.append("/");
    switch(query.subject()) {
        case DATASETS:
            sb.append(CAMPAIGNS_SUBJECT);
            break;
        case PARAMETERS:
            sb.append(PARAMETERS_SUBJECT);
            break;
        case OBSERVATIONS:
            sb.append(OBSERVATIONS_SUBJECT);
            break;
    }
    sb.append("?");
    for (int i = 0; i < queryParams.size(); i++) {
        String queryParam = queryParams.get(i);
        sb.append(queryParam);
        if (i < queryParams.size() - 1) {
            sb.append("&");
        }
    }
    return sb.toString();
}

public boolean startsWith(String prefix){
    return startsWith(prefix, 0);
}

public boolean contains(CharSequence s){
    return indexOf(s.toString()) > -1;
}

long count()

IntStream filter(IntPredicate predicate)

public default IntStream chars(){
    class CharIterator implements PrimitiveIterator.OfInt {

        int cur = 0;

        public boolean hasNext() {
            return cur < length();
        }

        public int nextInt() {
            if (hasNext()) {
                return charAt(cur++);
            } else {
                throw new NoSuchElementException();
            }
        }

        @Override
        public void forEachRemaining(IntConsumer block) {
            for (; cur < length(); cur++) {
                block.accept(charAt(cur));
            }
        }
    }
    return StreamSupport.intStream(() -> Spliterators.spliterator(new CharIterator(), length(), Spliterator.ORDERED), Spliterator.SUBSIZED | Spliterator.SIZED | Spliterator.ORDERED, false);
}

public int length(){
    return value.length;
}

