static File getFirstSlstrFile() throws URISyntaxException{
    return getResource(TestUtils.FIRST_FILE_NAME);
}

static File getThirdSlstrFile() throws URISyntaxException{
    return getResource(TestUtils.THIRD_FILE_NAME);
