    try {
        byte[] buffer = new byte[8];
        readMagicBytes(input, buffer);
        IOServiceProvider spi = getIOSpi(buffer);
        if (spi != null) {
            RandomAccessFile raf = getRaf(input);
            if (raf != null) {
                return new DummyNetcdfFile(spi, raf, raf.getLocation());
