public Section(int[] origin, int[] shape) throws InvalidRangeException{
    this.list = new ArrayList();
    for (int i = 0; i < shape.length; ++i) {
        if (shape[i] > 0) {
            this.list.add(new Range(origin[i], origin[i] + shape[i] - 1));
        } else if (shape[i] == 0) {
            this.list.add(Range.EMPTY);
        } else {
            this.list.add(Range.VLEN);
        }
    }
}

public Array read(Section section) throws IOException, InvalidRangeException{
    return section == null ? this._read() : this._read(Section.fill(section, this.shape));
}

public Array read() throws IOException{
    return this._read();
}

