public Section(int[] origin, int[] shape) throws InvalidRangeException{
    this.list = new ArrayList();
    for (int i = 0; i < shape.length; ++i) {
        if (shape[i] > 0) {
            this.list.add(new Range(origin[i], origin[i] + shape[i] - 1));
        } else if (shape[i] == 0) {
            this.list.add(Range.EMPTY);
        } else {
            this.list.add(Range.VLEN);
        }
    }
}

