    assertEquals("2017-10-18T01:25:34.592568Z", elementMissingNodeAttributes.getNamedItem("startTime").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("stopTime"));
    assertEquals("2017-10-18T01:25:36.442568Z", elementMissingNodeAttributes.getNamedItem("stopTime").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("percentage"));
    assertEquals("0.856653", elementMissingNodeAttributes.getNamedItem("percentage").getNodeValue());
    final NodeList elementMissingNodeChildNodes = childNodes.item(2).getChildNodes();
    assertEquals(1, elementMissingNodeChildNodes.getLength());
    final Node bandSetNode = elementMissingNodeChildNodes.item(0);
    assertEquals("slstr:bandSet", bandSetNode.getNodeName());
    assertEquals(0, bandSetNode.getAttributes().getLength());
    assertEquals(1, bandSetNode.getChildNodes().getLength());
    assertEquals("S8", bandSetNode.getFirstChild().getNodeValue());
    assertEquals("S8", bandSetNode.getTextContent());
    assertEquals("slstr:elementMissing", childNodes.item(3).getNodeName());
    assert (childNodes.item(3).hasAttributes());
    final NamedNodeMap elementMissingNodeAttributes = childNodes.item(3).getAttributes();
    assertEquals(5, elementMissingNodeAttributes.getLength());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("grid"));
    assertEquals("1 km", elementMissingNodeAttributes.getNamedItem("grid").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("view"));
    assertEquals("Oblique", elementMissingNodeAttributes.getNamedItem("view").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("startTime"));
    assertEquals("2017-10-18T01:25:36.942504Z", elementMissingNodeAttributes.getNamedItem("startTime").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("stopTime"));
    assertEquals("2017-10-18T01:25:38.142447Z", elementMissingNodeAttributes.getNamedItem("stopTime").getNodeValue());
