            }
        }
    }
    for (int i = 0; i < elementNames.size(); i++) {
        final Element newElement = toDocument.createElement(elementNames.get(i));
        newElement.setAttribute("percentage", percentageValues.get(i).toString());
        toParent.appendChild(newElement);
    }
}

