static String createParentDirectoryNameOfStitchedFile(SlstrNameDecomposition[] slstrNameDecompositions, Date now){
    Date startTime = extractStartTime(slstrNameDecompositions);
    Date stopTime = extractStopTime(slstrNameDecompositions);
    final StringBuilder slstrNameStringBuilder = new StringBuilder("S3A_SL_1_RBT___");
    String[] slstrNameParts = new String[] { SLSTR_DATE_FORMAT_CONVERTER.format(startTime), SLSTR_DATE_FORMAT_CONVERTER.format(stopTime), SLSTR_DATE_FORMAT_CONVERTER.format(now), slstrNameDecompositions[0].duration, slstrNameDecompositions[0].cycleNumber, slstrNameDecompositions[0].relativeOrbitNumber, slstrNameDecompositions[0].frameAlongTrackCoordinate, slstrNameDecompositions[0].fileGeneratingCentre, slstrNameDecompositions[0].platform, slstrNameDecompositions[0].timelinessOfProcessingWorkflow, slstrNameDecompositions[0].baselineCollectionOrDataUsage };
    for (String namePart : slstrNameParts) {
        slstrNameStringBuilder.append("_").append(namePart);
    }
    slstrNameStringBuilder.append(".SEN3");
    return slstrNameStringBuilder.toString();
}

public final String format(Date date){
    return format(date, new StringBuffer(), DontCareFieldPosition.INSTANCE).toString();
}

public SimpleDateFormat(String pattern){
    this(pattern, Locale.getDefault(Locale.Category.FORMAT));
}

