// Test prefix
public void testGetSpectralInputString() throws Exception {
    System.setProperty(LandsatGeotiffReader.SYSPROP_READ_AS, "reflectance");
    assertEquals("REFLECTANCE", Landsat8Metadata.getSpectralInputString());
    System.setProperty(LandsatGeotiffReader.SYSPROP_READ_AS, "radiance");
    <extra_id_0>
}

// Junit Version
JUnit 4

// Invoked methods in test prefix
public static String setProperty(String key, String value){
    checkKey(key);
    SecurityManager sm = getSecurityManager();
    if (sm != null) {
        sm.checkPermission(new PropertyPermission(key, SecurityConstants.PROPERTY_WRITE_ACTION));
    }
    return (String) props.setProperty(key, value);
}

static String getSpectralInputString(){
    final Preferences preferences = Config.instance("s3tbx").load().preferences();
    final String readAs = preferences.get(LandsatGeotiffReader.SYSPROP_READ_AS, null);
    String spectralInput;
    if (readAs != null) {
        switch(readAs.toLowerCase()) {
            case LandsatGeotiffReader.READ_AS_REFLECTANCE:
                spectralInput = "REFLECTANCE";
                break;
            case "radiance":
                spectralInput = "RADIANCE";
                break;
            default:
                spectralInput = "RADIANCE";
                LOG.warning(String.format("Property '%s' has unsupported value '%s'.%n" + "Interpreting values as radiance.", LandsatGeotiffReader.SYSPROP_READ_AS, readAs));
        }
    } else {
        spectralInput = "RADIANCE";
    }
    return spectralInput;
}

