// Invoked methods in test prefix
public static void writeRecordData(final ImageOutputStream ios) throws IOException{
    // recordNumber = 1
    ios.writeInt(1);
    // firstRecordSubtype = 77 octal
    ios.write(077);
    // recordTypeCode = 300 octal
    ios.write(0300);
    // secondRecordSubtype = 22 octal
    ios.write(022);
    // thirdRecordSubtype = 22 octal (21 octal only for test)
    ios.write(021);
    // recordLength = variable
    ios.writeInt(RECORD_LENGTH);
}

public void writeBytes(String s) throws IOException{
    int len = s.length();
    for (int i = 0; i < len; i++) {
        write((byte) s.charAt(i));
    }
}

public static void writeBlanks(final ImageOutputStream ios, final int numBlanks) throws IOException{
    final char[] chars = new char[numBlanks];
    Arrays.fill(chars, ' ');
    ios.writeBytes(new String(chars));
}

public long getStreamPosition() throws IOException{
    checkClosed();
    return streamPos;
}

public static void assertRecord(final BaseRecord record){
    assertNotNull(record);
    assertEquals(1, record.getRecordNumber());
    assertEquals(077, record.getFirstRecordSubtype());
    assertEquals(0300, record.getRecordTypeCode());
    assertEquals(022, record.getSecondRecordSubtype());
    assertEquals(021, record.getThirdRecordSubtype());
    assertEquals(RECORD_LENGTH, record.getRecordLength());
}

