// Test prefix
public void testInitRecord() throws IOException, IllegalCeosFormatException {
    BaseRecordTest.writeRecordData(_ios);
    // numNominalPixelsPerLine // I16
    _ios.writeBytes("           16959");
    // numNominalLinesPerScene // I16
    _ios.writeBytes("           14000");
    // sceneCenterInterPixelDistance // F16.7
    _ios.writeBytes("       2.5000000");
    // sceneCenterInterLineDistance // F16.7
    _ios.writeBytes("       3.5000000");
    // sceneCenterImageSkew // F16.7
    _ios.writeBytes("       4.5000000");
    // hemisphere // I4
    _ios.writeBytes("   1");
    // UTM_ZoneNumber // I12
    _ios.writeBytes("35          ");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // sceneCenterNorthing // F16.7
    _ios.writeBytes("       5.5000000");
    // sceneCenterEasting // F16.7
    _ios.writeBytes("       6.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // angleBetweenMapUTMVerticalAndTrueNorth // F16.7
    _ios.writeBytes("       7.5000000");
    // 112 x blank
    CeosTestHelper.writeBlanks(_ios, 112);
    // mapProjOriginLat // F16.7
    _ios.writeBytes("       8.5000000");
    // mapProjOriginLon // F16.7
    _ios.writeBytes("       9.5000000");
    // reference latitude // F16.7
    _ios.writeBytes("      10.5000000");
    // reference longitude // F16.7
    _ios.writeBytes("      11.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // X coordinates of the scene center (km) // F16.7
    _ios.writeBytes("      12.5000000");
    // Y coordinates of the scene center (km) // F16.7
    _ios.writeBytes("      13.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // angleBetweenMapPSVerticalAndTrueNorth // F16.7
    _ios.writeBytes("      14.5000000");
    // numNominalPixelsPerLine // F16.7
    _ios.writeBytes("      15.5000000");
    // numNominalLinesPerScene // F16.7
    _ios.writeBytes("      16.5000000");
    // nominalOututInterPixelDistance // F16.7
    _ios.writeBytes("      17.5000000");
    // nominalOutputInterLineDistance // F16.7
    _ios.writeBytes("      18.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // angleBetweenMapVerticalAndTrueNorth // F16.7
    _ios.writeBytes("      19.5000000");
    // nominalSateliteOrbitInclination // F16.7
    _ios.writeBytes("      20.5000000");
    // nominalAscendingNodeLon // F16.7
    _ios.writeBytes("      21.5000000");
    // nominalSateliteAltitude // F16.7
    _ios.writeBytes("      22.5000000");
    // nominalGroundSpeed // F16.7
    _ios.writeBytes("      23.5000000");
    // satteliteHeadingAngleIncludingEarthRotationOfSceneCenter // F16.7
    _ios.writeBytes("      24.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // swathAngle // F16.7
    _ios.writeBytes("      25.5000000");
    // nominalScanRate // F16.7
    _ios.writeBytes("      26.5000000");
    // nameReferenceEllipsoid // A16
    _ios.writeBytes("kjfojmekmvdoklms");
    // semimajorAxisOfReferenceEllipsoid // F16.7
    _ios.writeBytes("      27.5000000");
    // semiminorAxisOfReferenceEllipsoid // F16.7
    _ios.writeBytes("      28.5000000");
    // nameGeodeticCoordinates // A16
    _ios.writeBytes("uih0897n434kljss");
    // 128 x blank
    CeosTestHelper.writeBlanks(_ios, 128);
    // write latitude coeffs
    _ios.writeBytes(" 3.51762825378903869E+01" + "-3.72525633118785182E-06" + "-2.22154479999701052E-05" + " 6.75514377303297257E-13" + "-3.08409114105194292E-12" + "-6.47199691979237372E-14" + " 2.33148210051737742E-18" + "-8.25004293603135684E-19" + " 3.89695931047396857E-19" + " 7.62881323267747713E-20");
    // write longitude coeffs
    _ios.writeBytes(" 1.38257153591810379E+02" + " 2.70569048022997204E-05" + "-4.53710988950547022E-06" + "-7.30238602559696922E-12" + "-1.03702398000958172E-12" + " 1.03698394927313316E-12" + " 1.91908097005926553E-18" + " 3.69386366596817251E-18" + "-1.23128778809667902E-18" + "-6.39669024583341597E-19");
    // write X coeffs
    _ios.writeBytes("-4.17920143679666659E+06" + "-1.45568010437627992E+05" + " 3.86479338596612215E+04" + "-1.23862070427656249E+03" + " 7.24502994104848858E+03" + " 2.32251035691070371E+02" + " 1.57097184834409962E+01" + "-1.06636783607930674E+00" + "-8.96152721026457897E+01" + "-5.65286440987201266E-01");
    // write Y coeffs
    _ios.writeBytes(" 2.15921675754298194E+05" + " 1.04608585586919016E+04" + " 5.76886918796067948E+03" + " 5.65591484966379028E+01" + "-1.84864330812192475E+03" + " 7.36076275871487837E+01" + " 9.12008243626968529E+00" + "-2.15733856129907675E+00" + " 5.52849921945469802E+00" + "-4.26207159240670652E-01");
    // write 6 coefficients for F4 function
    writeIncrementingDoubles(10.23456, 6, _ios);
    writeCoefficients(_ios);
    CeosTestHelper.writeBlanks(_ios, (int) (RECORD_LENGTH - _ios.getStreamPosition()));
    final Ancillary1Record record = createAncillary1Record(_reader, _prefix.length());
    BaseRecordTest.assertRecord(record);
    assertEquals(_prefix.length(), record.getStartPos());
    assertEquals(_prefix.length() + RECORD_LENGTH, _ios.getStreamPosition());
    assertEquals(16959, record.getNumNominalPixelsPerLine_1A_1B1());
