    _ios.writeBytes(" 3.51762825378903869E+01" + "-3.72525633118785182E-06" + "-2.22154479999701052E-05" + " 6.75514377303297257E-13" + "-3.08409114105194292E-12" + "-6.47199691979237372E-14" + " 2.33148210051737742E-18" + "-8.25004293603135684E-19" + " 3.89695931047396857E-19" + " 7.62881323267747713E-20");
    // write longitude coeffs
