    // swathAngle // F16.7
    _ios.writeBytes("      25.5000000");
    // nominalScanRate // F16.7
    _ios.writeBytes("      26.5000000");
    // nameReferenceEllipsoid // A16
    _ios.writeBytes("kjfojmekmvdoklms");
    // semimajorAxisOfReferenceEllipsoid // F16.7
    _ios.writeBytes("      27.5000000");
    // semiminorAxisOfReferenceEllipsoid // F16.7
    _ios.writeBytes("      28.5000000");
    // nameGeodeticCoordinates // A16
    _ios.writeBytes("uih0897n434kljss");
    // 128 x blank
    CeosTestHelper.writeBlanks(_ios, 128);
    // write latitude coeffs
    _ios.writeBytes(" 3.51762825378903869E+01" + "-3.72525633118785182E-06" + "-2.22154479999701052E-05" + " 6.75514377303297257E-13" + "-3.08409114105194292E-12" + "-6.47199691979237372E-14" + " 2.33148210051737742E-18" + "-8.25004293603135684E-19" + " 3.89695931047396857E-19" + " 7.62881323267747713E-20");
    // write longitude coeffs
    _ios.writeBytes(" 1.38257153591810379E+02" + " 2.70569048022997204E-05" + "-4.53710988950547022E-06" + "-7.30238602559696922E-12" + "-1.03702398000958172E-12" + " 1.03698394927313316E-12" + " 1.91908097005926553E-18" + " 3.69386366596817251E-18" + "-1.23128778809667902E-18" + "-6.39669024583341597E-19");
    // write X coeffs
