    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // sceneCenterNorthing // F16.7
    _ios.writeBytes("       5.5000000");
    // sceneCenterEasting // F16.7
    _ios.writeBytes("       6.5000000");
