    _ios.writeBytes("      12.5000000");
    // Y coordinates of the scene center (km) // F16.7
    _ios.writeBytes("      13.5000000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
