public TrailerFileDescriptorRecord(final CeosFileReader reader) throws IOException, IllegalCeosFormatException{
    this(reader, -1);
}

public static void assertRecord(final CommonFileDescriptorRecord record){
    BaseRecordTest.assertRecord(record);
    assertEquals("A ", record.getCodeCharacter());
    // fileDocumentNumber // A12
    assertEquals("manno       ", record.getFileDocumentNumber());
    // fileDokumentRevisionNumber // A2
    assertEquals("A ", record.getFileDokumentRevisionNumber());
    // fileDesignRevisionLetter // A2
    assertEquals("A ", record.getFileDesignRevisionLetter());
    // logicalVolPrepSysRelNum //A12
    assertEquals("prdsys      ", record.getLogicalVolPrepSysRelNum());
    // fileNumber // I4
    assertEquals(1, record.getFileNumber());
    // fileID // A16
    assertEquals("AL PSMB2LEADBSQ ", record.getFileID());
    // flagRecordComposition // A4
    assertEquals("FSEQ", record.getFlagRecordComposition());
    // recordNumberPositionOfEachFile // I8
    assertEquals(1, record.getRecordNumberPositionOfEachFile());
    // fieldLengthForRecordData // I4
    assertEquals(4, record.getFieldLengthForRecordData());
    // flagOfRecordTypeCode // A4
    assertEquals("FTYP", record.getFlagOfRecordTypeCode());
    // recordTypeCodeBytePosition // I8
    assertEquals(5, record.getRecordTypeCodeBytePosition());
    // recordTypeCodeFieldLength // I4
    assertEquals(4, record.getRecordTypeCodeFieldLength());
    // flagRecordLength // A4
    assertEquals("FLGT", record.getFlagRecordLength());
    // bytePosOfRecLenth // I8
    assertEquals(9, record.getBytePosOfRecLength());
    // numOfBytesOfRecLength // I4
    assertEquals(4, record.getNumOfBytesOfRecLength());
    // flagDataConvInfFileDescRec // A1
    assertEquals("N", record.getFlagDataConvInfFileDescRec());
    // flagDataConvInOtherRecords // A1
    assertEquals("O", record.getFlagDataConvInOtherRecords());
    // flagDataDispFileDescRecord // A1
    assertEquals("P", record.getFlagDataDispFileDescRecord());
    // flagDataDispInOtherRecords // A1
    assertEquals("Q", record.getFlagDataDispInOtherRecords());
}

